{"code":"const result = await page.evaluate(() => {
  // Let's inspect the entire iframe tree and all elements and styles inside
  const outerFrame = document.querySelector('iframe');
  if (!outerFrame) return { error: "no outer iframe" };
  const outerDoc = outerFrame.contentDocument;
  if (!outerDoc) return { error: "no outer doc" };

  const innerFrame = outerDoc.querySelector('iframe');
  if (!innerFrame) return { error: "no inner iframe" };
  const innerDoc = innerFrame.contentDocument;
  if (!innerDoc) return { error: "no inner doc" };

  const getStyles = (el) => {
    const computed = el ? el.ownerDocument.defaultView.getComputedStyle(el) : null;
    return computed ? {
      bg: computed.backgroundColor,
      color: computed.color,
      font: computed.fontFamily
    } : null;
  };

  const allRulesFor = (doc, el) => {
    const rules = [];
    for (const sheet of Array.from(doc.styleSheets)) {
      try {
        for (const rule of Array.from(sheet.cssRules || [])) {
          if (rule.selectorText && el.matches(rule.selectorText)) {
            rules.push({
              sheet: sheet.href || 'inline',
              selector: rule.selectorText,
              css: rule.cssText
            });
          }
        }
      } catch (e) {
        rules.push({ sheet: sheet.href, error: e.message });
      }
    }
    return rules;
  };

  return {
    outerHtml: getStyles(outerDoc.documentElement),
    outerBody: getStyles(outerDoc.body),
    outerBodyRules: allRulesFor(outerDoc, outerDoc.body),
    innerHtml: getStyles(innerDoc.documentElement),
    innerBody: getStyles(innerDoc.body),
    innerHtmlRules: allRulesFor(innerDoc, innerDoc.documentElement),
    innerBodyRules: allRulesFor(innerDoc, innerDoc.body),
    runnerResultClasses: innerFrame.className,
    runnerResultStyles: innerFrame.getAttribute('style'),
  };
});
return JSON.stringify(result, null, 2);
